const output = $json.body ? $json.body.ai_output : {};
let parsed = output;
try { if (typeof output === 'string') parsed = JSON.parse(output); } catch(e){}
const validSymbols = ['NIFTY', 'BANKNIFTY', 'SENSEX', 'RELIANCE', 'HDFC', 'INFY', 'TCS'];
const symbolValid = !parsed.symbol || validSymbols.includes(parsed.symbol.toUpperCase());
const actionValid = ['BUY', 'SELL', 'HOLD'].includes((parsed.action || '').toUpperCase());
const valid = symbolValid && actionValid;
return [{ approved: valid, parsed }];
